		for (int i = 0; i < 4; i++) {
			builder.get();
		}
		int buildRounds = Math.max(5, Math.min(64, 4_096 / Math.max(1, rows.length)));
		long[] buildTimes = new long[buildRounds];
		Index index = null;
		for (int i = 0; i < buildRounds; i++) {
			long started = System.nanoTime();
			index = builder.get();
			buildTimes[i] = System.nanoTime() - started;
		}
		Arrays.sort(buildTimes);
		long buildNanos = buildTimes[buildTimes.length >>> 1];
		verify(rows, queries, index);
		for (int i = 0; i < WARMUP_ROUNDS; i++) {
			sink ^= execute(index, queries);
		}
		long[] elapsed = new long[MEASURE_ROUNDS];
		long checksum = 0;
