	private static long execute(Index index, long[] queries) {
		long checksum = 0;
		for (int repetition = 0; repetition < QUERY_REPETITIONS; repetition++) {
			for (long query : queries) {
				checksum += index.find(query);
			}
		}
		return checksum;
	}

	private static void verify(long[] rows, long[] queries, Index index) {
		for (int ordinal = 0; ordinal < rows.length; ordinal++) {
			if (index.find(rows[ordinal]) != ordinal) {
				throw new AssertionError(index.kind() + " missed row " + ordinal);
			}
		}
		for (long query : queries) {
			int expected = CsfRowLookupAccelerators.binarySearchUnsigned(rows, 0, rows.length - 1, query);
			if (index.find(query) != expected) {
				throw new AssertionError(index.kind() + " disagreed for " + Long.toUnsignedString(query));
			}
		}
	}

	private static long[] rows(int size, Distribution distribution) {
		long[] rows = new long[size];
		switch (distribution) {
		case TYPED_SEQUENTIAL -> {
			long payload = 1_000_000L;
			for (int i = 0; i < size; i++) {
				rows[i] = (payload + i) << 7 | 2L;
			}
		}
		case UNIFORM_UNSIGNED -> {
			long step = Long.divideUnsigned(-1L, size + 1L);
			for (int i = 0; i < size; i++) {
				rows[i] = step * (i + 1L);
			}
		}
		case CLUSTERED -> {
			int at = 0;
			for (int cluster = 0; cluster < 8; cluster++) {
				int end = cluster == 7 ? size : (cluster + 1) * size / 8;
				long base = 10_000L + (long) cluster * (1L << 36);
				while (at < end) {
					rows[at] = (base + at - cluster * size / 8L) << 7 | 2L;
					at++;
				}
			}
		}
		case COMMON_HIGH_PREFIX -> {
			Random random = new Random(0x434f_4d4d_4f4eL ^ size);
			long prefix = 0x7a12_3400_0000_0000L;
			for (int i = 0; i < size; i++) {
				rows[i] = prefix | random.nextLong(1L << 40);
			}
			sortUnsigned(rows);
			makeUnique(rows);
		}
		case RANDOM_GAPS -> {
			Random random = new Random(0x524f_5747_4150_53L ^ size);
			for (int i = 0; i < size; i++) {
				rows[i] = random.nextLong();
			}
			sortUnsigned(rows);
			makeUnique(rows);
		}
		}
		return rows;
	}

	private static long[] queries(long[] rows, Workload workload, long seed) {
		long[] result = new long[QUERY_COUNT];
		Random random = new Random(seed);
		switch (workload) {
		case RANDOM_HIT -> {
			for (int i = 0; i < result.length; i++) {
				result[i] = rows[random.nextInt(rows.length)];
			}
		}
		case MIXED_50 -> {
			for (int i = 0; i < result.length; i++) {
				result[i] = (i & 1) == 0 ? rows[random.nextInt(rows.length)] : absent(rows, random);
			}
		}
		case LOCAL_HIT -> {
			int ordinal = random.nextInt(rows.length);
			for (int i = 0; i < result.length; i++) {
				int movement = random.nextInt(10) < 9 ? random.nextInt(3) - 1 : random.nextInt(rows.length);
				ordinal = Math.floorMod(ordinal + movement, rows.length);
				result[i] = rows[ordinal];
			}
		}
		}
		return result;
	}

	private static long absent(long[] rows, Random random) {
		for (;;) {
			long candidate = rows[random.nextInt(rows.length)] + (random.nextLong() | 1L);
			if (CsfRowLookupAccelerators.binarySearchUnsigned(rows, 0, rows.length - 1, candidate) < 0) {
				return candidate;
			}
		}
	}

	private static void sortUnsigned(long[] rows) {
		for (int i = 0; i < rows.length; i++) {
			rows[i] ^= Long.MIN_VALUE;
		}
		Arrays.sort(rows);
		for (int i = 0; i < rows.length; i++) {
			rows[i] ^= Long.MIN_VALUE;
		}
	}

	private static void makeUnique(long[] rows) {
		for (int i = 1; i < rows.length; i++) {
			if (rows[i] == rows[i - 1]) {
				rows[i]++;
			}
		}
		sortUnsigned(rows);
	}

